<?php require_once __DIR__.'/../includes/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('INSERT INTO categories(name,slug,description) VALUES(?,?,?)');$s->execute([trim($_POST['name']),slugify($_POST['slug']?:$_POST['name']),trim($_POST['description'])]);redirect_to('admin/categories.php');}$rows=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$page_title='Categories';require __DIR__.'/../includes/header.php';?><section class="section-head"><h1>Categories</h1></section><div class="card"><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><input name="name" placeholder="Category name" required></p><p><input name="slug" placeholder="Slug"></p><p><textarea name="description" placeholder="Description" rows="4"></textarea></p><button class="btn">Add Category</button></form></div></div><div class="results"><?php foreach($rows as $r):?><article class="result"><b><?=e($r['name'])?></b> — <?=e($r['slug'])?></article><?php endforeach;?></div><?php require __DIR__.'/../includes/footer.php';?>
